using Jindan.Desktop.Contracts;
namespace Jindan.Desktop.UiTests;
static partial class Program {
 static Rectangle ScreenRectangle(Control control)=>control.RectangleToScreen(control.ClientRectangle);
 static object AssertPhotoDockLayout(RecordDocument photo){var grid=Grid(photo);var toolbar=Tree(photo).OfType<ToolStrip>().Single();var notice=photo.Controls.OfType<Label>().Single(l=>l.Dock==DockStyle.Bottom);var split=Tree(photo).OfType<SplitContainer>().Single();var header=grid.RectangleToScreen(new Rectangle(0,0,grid.ClientSize.Width,grid.ColumnHeadersHeight));var top=ScreenRectangle(toolbar);var bottom=ScreenRectangle(notice);var body=ScreenRectangle(split);Check(grid.ColumnHeadersVisible&&grid.ColumnHeadersHeight>0&&grid.Columns.Cast<DataGridViewColumn>().All(c=>!string.IsNullOrWhiteSpace(c.HeaderText)),"Native photo grid column captions are not enabled");Check(!header.IntersectsWith(top)&&!header.IntersectsWith(bottom),"Native photo header is occluded by toolbar or notice");Check(!body.IntersectsWith(top)&&!body.IntersectsWith(bottom),"Photo split overlaps docked toolbar or notice");Check(body.Height>0&&split.Panel1.Height>=grid.ColumnHeadersHeight&&split.Panel2.Height>0,"Photo split panels collapsed");return new{name="native photo docking geometry",physicalDpi=photo.DeviceDpi,header=new[]{header.X,header.Y,header.Width,header.Height},toolbar=new[]{top.X,top.Y,top.Width,top.Height},notice=new[]{bottom.X,bottom.Y,bottom.Width,bottom.Height},split=new[]{body.X,body.Y,body.Width,body.Height},headers=grid.Columns.Cast<DataGridViewColumn>().Select(c=>c.HeaderText).ToArray(),noOcclusion=true};}
 static void AssertTaskDockLayout(RecordDocument task,MonthCalendar calendar){var grid=Grid(task);var toolbar=Tree(task).OfType<ToolStrip>().Single();var notice=task.Controls.OfType<Label>().Single(l=>l.Dock==DockStyle.Bottom);var side=calendar.Parent??throw new InvalidOperationException("Native calendar parent missing");var header=grid.RectangleToScreen(new Rectangle(0,0,grid.ClientSize.Width,grid.ColumnHeadersHeight));var top=ScreenRectangle(toolbar);var bottom=ScreenRectangle(notice);var body=ScreenRectangle(grid);var calendarSide=ScreenRectangle(side);var native=ScreenRectangle(calendar);var single=calendar.SingleMonthSize;Samples.Add(new{name="native single-month calendar fit",physicalDpi=calendar.DeviceDpi,calendarDimensions=new[]{calendar.CalendarDimensions.Width,calendar.CalendarDimensions.Height},singleMonthSize=new[]{single.Width,single.Height},nativeCalendar=new[]{native.X,native.Y,native.Width,native.Height},parentPanel=new[]{calendarSide.X,calendarSide.Y,calendarSide.Width,calendarSide.Height},filter=Tree(task).OfType<CheckBox>().Select(c=>new[]{c.Left,c.Top,c.Width,c.Height}).ToArray()});Check(calendar.CalendarDimensions==new Size(1,1),"Native calendar expanded beyond one month");Check(calendar.Width>=single.Width&&calendar.Height>=single.Height&&calendarSide.Contains(native),"Native calendar is clipped by its side panel");Check(!header.IntersectsWith(top)&&!header.IntersectsWith(bottom),"Task grid headers are occluded by docked bars");Check(!calendarSide.IntersectsWith(top)&&!calendarSide.IntersectsWith(bottom),"Native calendar overlaps toolbar or notice");Check(body.Left>=calendarSide.Right,"Native task grid is occluded by the calendar");Samples.Add(new{name="native task docking geometry",header=new[]{header.X,header.Y,header.Width,header.Height},toolbar=new[]{top.X,top.Y,top.Width,top.Height},calendar=new[]{calendarSide.X,calendarSide.Y,calendarSide.Width,calendarSide.Height},grid=new[]{body.X,body.Y,body.Width,body.Height},noOcclusion=true});}
}
